  // VAT: line 1 (42500-4250)*21% = 8032, line 2 (28500-5700)*21% = 4788

  assert.deepEqual(totals, {
    subtotal: line1Total + line2Total,
    discount: line1Discount + line2Discount,
    vat: 12820,
    total: line1Total + line2Total - line1Discount - line2Discount + 12820,
  });
});

test('invoiceTotals with decimal discount percentage', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 1000, name: 'Design work (hour)', vatRate: 21, discountPercent: 12.5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const lineTotal = 10 * 1000; // 10000
  const discount = lineTotal * 12.5 / 100; // 1250
  const amountAfterDiscount = lineTotal - discount; // 8750
  const vat = amountAfterDiscount * 21 / 100; // 1837.5 -> 1838

  assert.deepEqual(totals, {
    subtotal: lineTotal,
    discount,
    vat: 1838,
    total: lineTotal - discount + 1838,
  });
});

