  });
});

test('invoiceTotals calculates VAT on amount after discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 10000, name: 'Design', vatRate: 21, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 100000
  // Discount: 100000 * 10% = 10000
  // Amount after discount: 90000
  // VAT: 90000 * 21% = 18900
  assert.deepEqual(totals, {
    subtotal: 100000,
    discount: 10000,
    vat: 18900,
    total: 100000 - 10000 + 18900,
  });
});

